@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_99bbd0390a87452b9a6bbcd6991c17fc.Models
@using sv_99bbd0390a87452b9a6bbcd6991c17fc.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_isRefreshing && _displayedRecipes is not null)
{
    <div class="alert alert-info py-1 px-2 d-inline-block" role="status">
        <span class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span>
        Refreshing&hellip;
    </div>
}

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-1">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_displayedRecipes is null)
{
    <p role="status"><em>Loading recipes&hellip;</em></p>
}
else if (_displayedRecipes.Count == 0)
{
    <p>No recipes found for this cuisine.</p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in GetSortedRecipes())
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _displayedRecipes;
    private bool _isRefreshing;
    private string? _errorMessage;

    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;
    private readonly CancellationTokenSource _disposeCts = new();

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId && _displayedRecipes is not null)
        {
            // Only the sort param (or nothing) changed — no reload needed.
            return;
        }

        await LoadRecipesAsync(CuisineId);
    }

    private async Task LoadRecipesAsync(int cuisineId)
    {
        // Cancel any in-flight request for a previous cuisine.
        await CancelPendingLoadAsync();

        _cts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        var token = _cts.Token;

        _errorMessage = null;
        _isRefreshing = _displayedRecipes is not null;

        // If this is the first load, StateHasChanged is called automatically
        // after OnParametersSetAsync. For refreshes we need an explicit call
        // so the "Refreshing…" indicator appears immediately.
        if (_isRefreshing)
        {
            StateHasChanged();
        }

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(cuisineId, token);

            // Guard against a stale response arriving after cancellation.
            if (token.IsCancellationRequested)
            {
                return;
            }

            _displayedRecipes = recipes;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Request was intentionally cancelled (new cuisine or dispose). Ignore.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync(CuisineId);
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_displayedRecipes is null)
        {
            return Enumerable.Empty<Recipe>();
        }

        return Sort?.ToLowerInvariant() switch
        {
